def is_not_prime(n: int) -> bool:
    if n <= 1:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return True
    return False

import heapq

def heap_queue_largest(numbers, n):
    return heapq.nlargest(n, numbers)

def find_Rotations(s: str) -> int:
    n = len(s)
    for i in range(1, n + 1):
        if n % i == 0:
            if s == s[i:] + s[:i]:
                return i
    return n

def remove_Occ(s, c):
    first = s.find(c)
    last = s.rfind(c)
    if first == -1:
        return s
    if first == last:
        return s[:first] + s[first+1:]
    return s[:first] + s[first+1:last] + s[last+1:]

import re

def text_lowercase_underscore(s: str) -> bool:
    return bool(re.fullmatch(r'[a-z]+(_[a-z]+)+', s))

def check(n: int) -> bool:
    rev = int(str(n)[::-1])
    return n == 2 * rev - 1

def count_Substrings(s: str) -> int:
    count = 0
    n = len(s)
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += int(s[j])
            if total == (j - i + 1):
                count += 1
    return count

def recursive_list_sum(lst):
    total = 0
    for item in lst:
        if isinstance(item, list):
            total += recursive_list_sum(item)
        else:
            total += item
    return total

def bell_number(n):
    bell = [0] * (n + 1)
    bell[0] = 1
    for i in range(1, n + 1):
        bell[i] = 0
        for j in range(i):
            bell[i] += bell[j] * comb(i - 1, j)
    return bell[n]

def comb(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c

def is_sublist(lst, sublst):
    n, m = len(lst), len(sublst)
    if m == 0:
        return True
    for i in range(n - m + 1):
        if lst[i:i+m] == sublst:
            return True
    return False

def get_equal(tuples):
    if not tuples:
        return True
    length = len(tuples[0])
    return all(len(t) == length for t in tuples)

def comb_sort(arr):
    gap = len(arr)
    shrink = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink)
        if gap <= 1:
            gap = 1
            sorted = True

        i = 0
        while i + gap < len(arr):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False
            i += 1

    return arr

def dif_Square(n: int) -> bool:
    # A number n can be represented as difference of two squares if and only if n is not of the form 4k+2
    return n % 4 != 2

def is_samepatterns(lst1, lst2):
    if len(lst1) != len(lst2):
        return False
    mapping1 = {}
    mapping2 = {}
    for a, b in zip(lst1, lst2):
        if a not in mapping1:
            mapping1[a] = b
        if b not in mapping2:
            mapping2[b] = a
        if (mapping1[a] != b) or (mapping2[b] != a):
            return False
    return True

import math

def volume_sphere(radius):
    return (4/3) * math.pi * radius**3

def sequence(n):
    seq = [0, 1]
    for i in range(2, n + 1):
        seq.append(seq[i - seq[i - 1]] + seq[seq[i - 1]])
    return seq[n]

import math

def surfacearea_sphere(radius):
    return 4 * math.pi * radius ** 2

def merge_dictionaries_three(d1, d2, d3):
    merged = {}
    for d in (d1, d2, d3):
        for k, v in d.items():
            if k not in merged:
                merged[k] = v
    return merged

def freq_count(lst):
    freq = {}
    for item in lst:
        freq[item] = freq.get(item, 0) + 1
    return freq

def is_undulating(n: int) -> bool:
    s = str(n)
    if len(s) < 3:
        return False
    a, b = s[0], s[1]
    if a == b:
        return False
    for i in range(len(s)):
        if i % 2 == 0 and s[i] != a:
            return False
        if i % 2 == 1 and s[i] != b:
            return False
    return True

def divisor(n: int) -> int:
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count

def frequency_lists(lst):
    freq = {}
    for sublist in lst:
        for item in sublist:
            freq[item] = freq.get(item, 0) + 1
    return freq

def multiply_num(nums):
    product = 1
    for num in nums:
        product *= num
    return product / len(nums)

def next_smallest_palindrome(n: int) -> int:
    def is_palindrome(x):
        s = str(x)
        return s == s[::-1]

    n += 1
    while not is_palindrome(n):
        n += 1
    return n

def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 1 and m == 0:
        return 1
    return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m)

def odd_Equivalent(s, n):
    count = 0
    length = len(s)
    for i in range(n):
        rotated = s[i % length:] + s[:i % length]
        if int(rotated, 2) % 2 == 1:
            count += 1
    return count

def common_in_nested_lists(lst):
    if not lst:
        return set()
    common_set = set(lst[0])
    for sublist in lst[1:]:
        common_set &= set(sublist)
    return common_set

def check_integer(s: str) -> bool:
    if s.startswith(('+', '-')):
        return s[1:].isdigit()
    return s.isdigit()

def search(arr):
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        # Ensure mid is even for comparison with next element
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid
    return arr[left]

def max_product_tuple(lst):
    max_product = 0
    for a, b in lst:
        product = abs(a * b)
        if product > max_product:
            max_product = product
    return max_product

def amicable_numbers_sum(n):
    def sum_of_divisors(x):
        total = 1
        p = 2
        while p * p <= x:
            if x % p == 0:
                total += p
                if p != x // p:
                    total += x // p
            p += 1
        return total if x != 1 else 0

    total_sum = 0
    for a in range(2, n + 1):
        b = sum_of_divisors(a)
        if b != a and b <= n:
            if sum_of_divisors(b) == a:
                total_sum += a
    return total_sum

import math

def angle_complex(a, b):
    return math.atan2(b.imag if isinstance(b, complex) else b, a)

def find_length(s: str) -> int:
    max_diff = float('-inf')
    current_diff = 0
    for char in s:
        val = 1 if char == '0' else -1
        current_diff += val
        if current_diff > max_diff:
            max_diff = current_diff
        if current_diff < 0:
            current_diff = 0
    return max_diff if max_diff > 0 else 0

def sum(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)
    total = 0
    for i in range(1, g + 1):
        if g % i == 0:
            total += i
    return total

def magic_square_test(matrix):
    n = len(matrix)
    # Check if matrix is square
    if any(len(row) != n for row in matrix):
        return False

    # Flatten the matrix and check if it contains all numbers from 1 to n*n
    flat = [num for row in matrix for num in row]
    if sorted(flat) != list(range(1, n*n + 1)):
        return False

    # Calculate the magic sum from the first row
    magic_sum = sum(matrix[0])

    # Check rows
    for row in matrix:
        if sum(row) != magic_sum:
            return False

    # Check columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != magic_sum:
            return False

    # Check diagonals
    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False
    if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
        return False

    return True
